<?php
declare(strict_types=1);
namespace App\Entity\Cms;
use Doctrine\DBAL\Types\Types; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] #[ORM\Table(name:'cardnext_cms_block')] #[ORM\HasLifecycleCallbacks]
class CmsBlock { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(inversedBy:'blocks')] #[ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private ?CmsPage $page=null; #[ORM\Column(length:12)] private string $locale=''; #[ORM\Column(length:32)] private string $type='rich_text'; #[ORM\Column] private int $position=0; #[ORM\Column] private bool $enabled=true; /** @var array<string,mixed> */ #[ORM\Column(type:Types::JSON)] private array $configuration=[]; #[ORM\Column(name:'created_at',type:Types::DATETIME_IMMUTABLE)] private \DateTimeImmutable $createdAt; #[ORM\Column(name:'updated_at',type:Types::DATETIME_IMMUTABLE)] private \DateTimeImmutable $updatedAt;
 public function __construct(){ $this->createdAt=$this->updatedAt=new \DateTimeImmutable();} public function getId():?int{return $this->id;} public function getPage():?CmsPage{return $this->page;} public function setPage(CmsPage $v):void{$this->page=$v;} public function getLocale():string{return $this->locale;} public function setLocale(string $v):void{$this->locale=$v;} public function getType():string{return $this->type;} public function setType(string $v):void{$this->type=$v;} public function getPosition():int{return $this->position;} public function setPosition(int $v):void{$this->position=$v;} public function isEnabled():bool{return $this->enabled;} public function setEnabled(bool $v):void{$this->enabled=$v;} /** @return array<string,mixed> */ public function getConfiguration():array{return $this->configuration;} /** @param array<string,mixed> $v */ public function setConfiguration(array $v):void{$this->configuration=$v;} #[ORM\PreUpdate] public function touch():void{$this->updatedAt=new \DateTimeImmutable();}
}
